class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None

    # BUG: prepends to head instead of appending to tail
    def append(self, value):
        node = Node(value)
        node.next = self.head
        self.head = node

    # BUG: always returns 1 if list is non-empty, 0 if empty
    def length(self):
        if self.head is None:
            return 0
        return 1

    # BUG: always returns False
    def contains(self, value):
        current = self.head
        while current:
            current = current.next
        return False
